func TestHistoryHeaderCacheRandomReadsAndByteBudget(t *testing.T) {
	c := &historyHeaderCache{limit: 4, byteLimit: 100}
	for i := 0; i < 20; i++ {
		k := historyHeaderKey{decodedSize: 100, digest: sha256.Sum256([]byte{byte(i)})}
		c.put(k, bytes.Repeat([]byte{byte(i)}, 60))
		if c.bytes > 100 || len(c.entries) > 4 {
			t.Fatal("unbounded cache")
		}
	}
	dir := t.TempDir()
	path := filepath.Join(dir, "random.seg")
	raw := make([]byte, 4*historyCompressChunkSize+9)
	rng := rand.New(rand.NewSource(123))
	rng.Read(raw)
	if err := compressBlobToFile(dir, path, raw, historyCompressChunkSize); err != nil {
		t.Fatal(err)
	}
	c = &historyHeaderCache{limit: 17, byteLimit: 20 << 10}
	for round := 0; round < 2; round++ {
		r, err := openCompressedBlockReader(path)
		if err != nil {
			t.Fatal(err)
		}
		r.prefixCache = c
		for i := 0; i < 1000; i++ {
			off := rng.Intn(len(raw))
			n := min(1+rng.Intn(4096), len(raw)-off)
			out := make([]byte, n)
			nr, err := r.ReadAt(out, int64(off))
			if err != nil || nr != n || !bytes.Equal(out, raw[off:off+n]) {
				t.Fatalf("round %d off %d size %d err %v", round, off, n, err)
			}
			if c.bytes > 20<<10 || len(c.entries) > 17 || len(r.metadataSignatures) > cbCacheBlocks {
				t.Fatal("cache bound exceeded")
			}
		}
		r.Close()
	}
}
