		hot := &rawdb.StateDomainChange{BlockNum: 2, TxNum: 22, Seq: hotSeq, FlatDomain: rawdb.StateFlatDomainKVLatest, Owner: owner, Generation: 7, Domain: kvdomains.SystemReward, Key: key, PrevExists: true, Prev: []byte("hot")}
